function splashInkDecodeData() {
  if (typeof SPLASH_INK_DATA !== 'string' || !SPLASH_INK_DATA) return null;
  var frags = SPLASH_INK_DATA.split('|');
  var out = [];
  for (var i = 0; i < frags.length; i++) {
    var frag = frags[i];
    if (!frag || frag.length < 5 || frag.charAt(1) !== ':') continue;
    var body = frag.slice(2);
    var semi = body.indexOf(';');
    if (semi < 1) continue;
    var dur = parseFloat(body.slice(0, semi));
    if (!isFinite(dur) || dur <= 0) return null;
    var raw = body.slice(semi + 1).split(';');
    var pts = [];
    for (var k = 0; k < raw.length; k++) {
      var f = raw[k].split(',');
      if (f.length < 4) continue;
      var x = parseInt(f[0], 10) / 2000;
      var y = parseInt(f[1], 10) / 2000;
      var p = parseInt(f[2], 10) / 100;
      var t = parseInt(f[3], 10) / 100;
      if (!isFinite(x) || !isFinite(y) || !isFinite(p) || !isFinite(t)) return null;
      pts.push([x, y, p < 0 ? 0 : (p > 1 ? 1 : p), t < 0 ? 0 : (t > 1 ? 1 : t)]);
    }
    if (pts.length < 2) continue;
    out.push({ kind: frag.charAt(0), dur: dur, pts: pts });
  }
  return out.length ? out : null;
}

// 向心 Catmull-Rom 插值：把间距不均的烘焙点变成等距密集点。
// 必须用 centripetal(alpha=0.5)：均匀参数化在长短段交界处会过冲，边缘出现鳞状锯齿。
function splashInkResample(ctrl, step) {
  var n = ctrl.length;
  if (n < 2) return [ctrl[0].slice(), ctrl[n - 1].slice()];
  var out = [];
  var A = 0.5;
  function at(i) { return ctrl[i < 0 ? 0 : (i > n - 1 ? n - 1 : i)]; }
  for (var i = 0; i < n - 1; i++) {
    var p0 = at(i - 1), p1 = at(i), p2 = at(i + 1), p3 = at(i + 2);
    var d01 = Math.pow(Math.hypot(p1[0] - p0[0], p1[1] - p0[1]) || 1e-7, A);
    var d12 = Math.pow(Math.hypot(p2[0] - p1[0], p2[1] - p1[1]) || 1e-7, A);
    var d23 = Math.pow(Math.hypot(p3[0] - p2[0], p3[1] - p2[1]) || 1e-7, A);
    var t0 = 0, t1 = t0 + d01, t2 = t1 + d12, t3 = t2 + d23;
    var segLen = Math.hypot(p2[0] - p1[0], p2[1] - p1[1]);
    var steps = Math.max(2, Math.ceil(segLen / step));
    for (var k = 0; k < steps; k++) {
      var u = k / steps;
      var t = t1 + (t2 - t1) * u;
      var a1x = ((t1 - t) * p0[0] + (t - t0) * p1[0]) / (t1 - t0);
      var a1y = ((t1 - t) * p0[1] + (t - t0) * p1[1]) / (t1 - t0);
      var a2x = ((t2 - t) * p1[0] + (t - t1) * p2[0]) / (t2 - t1);
      var a2y = ((t2 - t) * p1[1] + (t - t1) * p2[1]) / (t2 - t1);
      var a3x = ((t3 - t) * p2[0] + (t - t2) * p3[0]) / (t3 - t2);
      var a3y = ((t3 - t) * p2[1] + (t - t2) * p3[1]) / (t3 - t2);
      var b1x = ((t2 - t) * a1x + (t - t0) * a2x) / (t2 - t0);
      var b1y = ((t2 - t) * a1y + (t - t0) * a2y) / (t2 - t0);
      var b2x = ((t3 - t) * a2x + (t - t1) * a3x) / (t3 - t1);
      var b2y = ((t3 - t) * a2y + (t - t1) * a3y) / (t3 - t1);
      var cx = ((t2 - t) * b1x + (t - t1) * b2x) / (t2 - t1);
      var cy = ((t2 - t) * b1y + (t - t1) * b2y) / (t2 - t1);
      out.push([cx, cy,
        p1[2] + (p2[2] - p1[2]) * u,
        p1[3] + (p2[3] - p1[3]) * u]);
    }
  }
  out.push(ctrl[n - 1].slice());
  return out;
}

// 由密集中心线生成左右偏移点、累计弧长、时间轴
function splashInkBuildStroke(dense, S, ox, oy, wMinNorm, wMaxNorm) {
  var n = dense.length;
  var X = new Float64Array(n), Y = new Float64Array(n), W = new Float64Array(n);
  var T = new Float64Array(n);
  var minX = Infinity, maxX = -Infinity;
  for (var i = 0; i < n; i++) {
    X[i] = ox + dense[i][0] * S;
    Y[i] = oy + dense[i][1] * S;
    var w = (wMinNorm + dense[i][2] * (wMaxNorm - wMinNorm)) * S;
    W[i] = w < 1.1 ? 1.1 : w;
    T[i] = dense[i][3];
    if (X[i] < minX) minX = X[i];
    if (X[i] > maxX) maxX = X[i];
  }
  var LX = new Float64Array(n), LY = new Float64Array(n);
  var RX = new Float64Array(n), RY = new Float64Array(n);
  var cum = new Float64Array(n);
  for (var j = 0; j < n; j++) {
    var dx, dy;
    if (j === 0) { dx = X[1] - X[0]; dy = Y[1] - Y[0]; }
    else if (j === n - 1) { dx = X[n - 1] - X[n - 2]; dy = Y[n - 1] - Y[n - 2]; }
    else { dx = X[j + 1] - X[j - 1]; dy = Y[j + 1] - Y[j - 1]; }
    var len = Math.hypot(dx, dy) || 1;
    var nx = -dy / len, ny = dx / len;
    var half = W[j] * 0.5;
    LX[j] = X[j] + nx * half; LY[j] = Y[j] + ny * half;
    RX[j] = X[j] - nx * half; RY[j] = Y[j] - ny * half;
    cum[j] = j === 0 ? 0 : cum[j - 1] + Math.hypot(X[j] - X[j - 1], Y[j] - Y[j - 1]);
  }
  return {
    n: n, X: X, Y: Y, W: W, T: T,
    LX: LX, LY: LY, RX: RX, RY: RY,
    cum: cum, total: cum[n - 1], cx: (minX + maxX) * 0.5
  };
}

// 时间 -> 点索引（T 单调不减，二分）
function splashInkIndexAtTime(geo, tf) {
  var n = geo.n, T = geo.T;
  if (tf <= 0) return 0;
  if (tf >= 1) return n - 1;
  var lo = 0, hi = n - 1;
  while (lo < hi) {
    var mid = (lo + hi + 1) >> 1;
    if (T[mid] <= tf) lo = mid; else hi = mid - 1;
  }
  return lo;
}

// 画出 [from, to] 区间的笔画（区间内的四边形 + 两端圆头）
function splashInkDrawRange(ctx, geo, from, to) {
  if (!geo || geo.n < 2) return;
  var a = Math.max(0, from | 0);
  var b = Math.min(geo.n - 1, to | 0);
  if (b < a) return;
  if (b > a) {
    ctx.beginPath();
    for (var i = a + 1; i <= b; i++) {
      // 统一绕向：笔画在折返处相邻四边形的绕向会相反，
      // 同路径 nonzero 填充时重叠区会互相抵消 -> 墨迹里出现白洞。
      var ax = geo.LX[i - 1], ay = geo.LY[i - 1];
      var bx = geo.LX[i], by = geo.LY[i];
      var cx = geo.RX[i], cy = geo.RY[i];
      var dx2 = geo.RX[i - 1], dy2 = geo.RY[i - 1];
      var area = (bx - ax) * (cy - ay) - (by - ay) * (cx - ax)
        + (cx - ax) * (dy2 - ay) - (cy - ay) * (dx2 - ax);
      if (area < 0) {
        ctx.moveTo(ax, ay); ctx.lineTo(dx2, dy2); ctx.lineTo(cx, cy); ctx.lineTo(bx, by);
      } else {
        ctx.moveTo(ax, ay); ctx.lineTo(bx, by); ctx.lineTo(cx, cy); ctx.lineTo(dx2, dy2);
      }
      ctx.closePath();
    }
    ctx.fill();
  }
  // 圆头必须单独一次 fill：与四边形同路径填充时绕向相反，重叠处按非零规则会互相抵消成白洞
  ctx.beginPath();
  ctx.moveTo(geo.X[a] + geo.W[a] * 0.5, geo.Y[a]);
  ctx.arc(geo.X[a], geo.Y[a], geo.W[a] * 0.5, 0, Math.PI * 2);
  ctx.moveTo(geo.X[b] + geo.W[b] * 0.5, geo.Y[b]);
  ctx.arc(geo.X[b], geo.Y[b], geo.W[b] * 0.5, 0, Math.PI * 2);
  ctx.fill();
}

function createSplashInkRenderer(canvas, cfg) {
  var ctx = canvas.getContext('2d');
  if (!ctx) return null;
  var frags = splashInkDecodeData();
  if (!frags) return null;

  var host = canvas.parentNode;
  var fontEl = cfg && cfg.fontEl;
  var reduceMotion = !!(cfg && cfg.reduceMotion);

  var entryFrag = null;
  var exitFrags = [];
  var inkFrags = [];
  for (var fi = 0; fi < frags.length; fi++) {
    var fr = frags[fi];
    if (fr.kind === 'e') entryFrag = fr;
    else if (fr.kind === 'x') exitFrags.push(fr);
    else inkFrags.push(fr);
  }
  if (!inkFrags.length) return null;

  var inkBox = SPLASH_INK_INK_BOX;
  var stageHn = SPLASH_INK_STAGE_H / SPLASH_INK_STAGE_W;

  var cssW = 0, cssH = 0, dpr = 1, inkWpx = 0, inkHpx = 0;
  var S = 1, ox = 0, oy = 0;

  var entry = null;
  var exits = [];
  var ink = [];
  var drop = null;
  var bodyStart = 0, jumpStart = 0, totalMs = 0;

  var staticCv = null, staticCtx = null;
  var started = false, finished = false, rafId = 0, elapsedMs = 0, lastFrameAt = 0;

  function measure() {
    var box = host && host.getBoundingClientRect ? host.getBoundingClientRect() : null;
    var hostW = box && box.width > 20 ? box.width : 760;
    var fs = 148;
    if (fontEl && window.getComputedStyle) {
      var v = parseFloat(window.getComputedStyle(fontEl).fontSize);
      if (isFinite(v) && v > 8) fs = v;
    }
    var inkH = fs * SPLASH_INK_INK_EM;
    var sc = inkH / inkBox[3];
    var inkW = inkBox[2] * sc;
    var maxInkW = hostW * 1.10;
    if (inkW > maxInkW) { sc *= maxInkW / inkW; inkW = maxInkW; inkH = inkBox[3] * sc; }
    // inkBox 的 y 也以「舞台宽」为 1，换算成「舞台高」为 1 才能算画布高
    var cxN = inkBox[0] + inkBox[2] * 0.5;
    var inkCyN = inkBox[1] + inkBox[3] * 0.5;
    var cyN = inkCyN / stageHn;
    var halfW = Math.max(cxN, 1 - cxN) * sc * 1.02;
    var halfH = Math.max(cyN, 1 - cyN) * stageHn * sc * 1.02;
    var cw = Math.min(hostW * 1.4, Math.max(120, halfW * 2));
    var ch = Math.min(hostW * 1.6, Math.max(80, halfH * 2));
    return { cw: cw, ch: ch, sc: sc, ox: cw / 2 - cxN * sc, oy: ch / 2 - inkCyN * sc, inkW: inkW, inkH: inkH };
  }

  function buildGeos(m) {
    var wMin = SPLASH_INK_W_MIN * inkBox[2];
    var wMax = SPLASH_INK_W_MAX * inkBox[2];
    var step = 1.0 / m.sc;   // 每 1 显示像素采样一次
    function mk(frag) {
      return splashInkBuildStroke(splashInkResample(frag.pts, step), m.sc, m.ox, m.oy, wMin, wMax);
    }
    entry = entryFrag ? { geo: mk(entryFrag), dur: entryFrag.dur } : null;
    exits = [];
    for (var e = 0; e < exitFrags.length; e++) {
      exits.push({ geo: mk(exitFrags[e]), dur: exitFrags[e].dur });
    }
    ink = [];
    drop = null;
    for (var i = 0; i < inkFrags.length; i++) {
      var item = {
        geo: mk(inkFrags[i]),
        dur: inkFrags[i].dur,
        isDroplet: inkFrags[i].kind === 'd',
        start: 0, committed: false
      };
      ink.push(item);
      if (item.isDroplet) drop = item;
    }
  }

  function buildTimeline(m) {
    var gap = SPLASH_INK_GAP_MS;

    // 按笔画序号硬分两段：「miner」和「adio」各走自己的真实笔速、同时落笔。
    // 不用几何中线自动分组——笔顺里 d 的竖（si=7）比 d 的圈（si=8）更靠右，
    // 按 x 分组会把同一个字母拆到两边。
    var splitAt = SPLASH_INK_SPLIT_AT;
    if (!(splitAt > 0 && splitAt < ink.length)) splitAt = Math.ceil(ink.length / 2);
    var left = [], right = [];
    for (var i = 0; i < ink.length; i++) {
      (i < splitAt ? left : right).push(i);
    }

    var totalL = 0, totalR = 0;
    for (var a = 0; a < left.length; a++) totalL += ink[left[a]].dur;
    for (var b = 0; b < right.length; b++) totalR += ink[right[b]].dur;
    totalL += Math.max(0, left.length - 1) * gap;
    totalR += Math.max(0, right.length - 1) * gap;
    var k = 1 / Math.max(0.25, SPLASH_INK_SPEED);

    bodyStart = (entry ? entry.dur * k : 0) + SPLASH_INK_ENTRY_HOLD_MS;

    var accL = bodyStart, accR = bodyStart;
    for (var c = 0; c < left.length; c++) {
      var it = ink[left[c]];
      it.start = accL;
      it.dur = it.dur * k;
      accL += it.dur + gap * k;
    }
    for (var d2 = 0; d2 < right.length; d2++) {
      var it2 = ink[right[d2]];
      it2.start = accR;
      it2.dur = it2.dur * k;
      accR += it2.dur + gap * k;
    }
    var bodyEnd = bodyStart + Math.max(totalL, totalR) * k;

    // 出线：同样按倍率缩放，但有下限，别快到看不见
    var exitStart = bodyEnd + SPLASH_INK_EXIT_GAP_MS;
    var exitEnd = exitStart;
    for (var y = 0; y < exits.length; y++) {
      var ex = exits[y];
      var st = exitStart + y * SPLASH_INK_EXIT_STAGGER_MS;
      ex.dur = Math.max(SPLASH_INK_MIN_EXIT_MS, ex.dur * k);
      ex.start = st;
      if (st + ex.dur > exitEnd) exitEnd = st + ex.dur;
    }

    if (entry) {
      entry.drawMs = entry.dur * k;
      entry.shrinkStart = bodyStart - 40;
    }

    jumpStart = bodyEnd + SPLASH_INK_DROPLET_DELAY_MS;
    totalMs = Math.max(
      jumpStart + SPLASH_INK_DROPLET_MS,
      exitEnd + SPLASH_INK_SHRINK_MS,
      bodyEnd + 400
    );
  }

  function layout() {
    var m = measure();
    cssW = m.cw; cssH = m.ch;
    inkWpx = m.inkW; inkHpx = m.inkH;
    S = m.sc; ox = m.ox; oy = m.oy;
    dpr = Math.min(window.devicePixelRatio || 1, 2.5);
    canvas.width = Math.max(1, Math.round(cssW * dpr));
    canvas.height = Math.max(1, Math.round(cssH * dpr));
    canvas.style.width = cssW + 'px';
    canvas.style.height = cssH + 'px';
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);

    if (!staticCv) staticCv = document.createElement('canvas');
    staticCv.width = canvas.width;
    staticCv.height = canvas.height;
    staticCtx = staticCv.getContext('2d');
    staticCtx.setTransform(dpr, 0, 0, dpr, 0, 0);
    staticCtx.fillStyle = SPLASH_INK_COLOR;

    buildGeos(m);
    buildTimeline(m);
    reset(true);
  }

  function reset(clearAll) {
    for (var i = 0; i < ink.length; i++) ink[i].committed = false;
    if (staticCtx) staticCtx.clearRect(0, 0, cssW, cssH);
    if (clearAll) ctx.clearRect(0, 0, cssW, cssH);
  }

  function drawTimeRange(geo, t0, t1) {
    if (!(t1 > t0)) return;          // 收缩到底（t0===t1）时什么都不留，否则尾端会剩一个圆点
    var a = splashInkIndexAtTime(geo, t0);
    var b = splashInkIndexAtTime(geo, t1);
    if (b < a) return;
    if (b === a) {
      // 只有一点：画一个圆头（落笔的第一团墨）
      ctx.beginPath();
      ctx.moveTo(geo.X[a] + geo.W[a] * 0.5, geo.Y[a]);
      ctx.arc(geo.X[a], geo.Y[a], geo.W[a] * 0.5, 0, Math.PI * 2);
      ctx.fill();
      return;
    }
    splashInkDrawRange(ctx, geo, a, b);
  }

  function drawDroplet(elapsed) {
    if (!drop || !drop.geo) return;
    var g = drop.geo;
    if (elapsed < drop.start) return;
    var local = (elapsed - drop.start) / drop.dur;
    if (elapsed < jumpStart) {
      drawTimeRange(g, 0, Math.min(1, local));
      return;
    }
    var p = (elapsed - jumpStart) / SPLASH_INK_DROPLET_MS;
    if (p > 1) p = 1;
    var sinP = Math.sin(p * Math.PI);
    var lift = -0.150 * inkWpx * sinP;
    var spread = (0.0417 * sinP + 0.0324 * p) * inkWpx;
    var rScale = 1 - 0.5 * p;
    var csx = 1 - 0.2 * p, csy = 1 + 0.6 * sinP;
    var ccx = 0, ccy = 0;
    for (var i = 0; i < g.n; i++) { ccx += g.X[i]; ccy += g.Y[i]; }
    ccx /= g.n; ccy /= g.n;
    var dirs = [-1, 0, 1];
    ctx.beginPath();
    for (var k = 0; k < 3; k++) {
      var dir = dirs[k];
      var dX = dir * spread;
      var ang = dir * p * 0.35;
      var ca = Math.cos(ang), sa = Math.sin(ang);
      for (var j = 0; j < g.n; j++) {
        var dx = g.X[j] - ccx, dy = g.Y[j] - ccy;
        var nx = ccx + (dx * ca - dy * sa) * csx + dX;
        var ny = ccy + (dx * sa + dy * ca) * csy + lift;
        var r = g.W[j] * 0.5 * rScale;
        if (r < 0.5) continue;
        ctx.moveTo(nx + r, ny);
        ctx.arc(nx, ny, r, 0, Math.PI * 2);
      }
    }
    ctx.fill();
  }

  function renderFrame(elapsed) {
    // 1) 已写完的普通笔画落进静态层（避免每帧重画全部四边形）
    for (var i = 0; i < ink.length; i++) {
      var s = ink[i];
      if (s.committed || s.isDroplet) continue;
      if (elapsed >= s.start + s.dur) {
        splashInkDrawRange(staticCtx, s.geo, 0, s.geo.n - 1);
        s.committed = true;
      }
    }
    ctx.clearRect(0, 0, cssW, cssH);
    ctx.drawImage(staticCv, 0, 0, cssW, cssH);
    ctx.fillStyle = SPLASH_INK_COLOR;

    // 2) 画进线：先整条画出，落笔后从头收缩
    if (entry) {
      var f0 = 0, f1 = 1;
      if (elapsed < entry.drawMs) {
        f1 = Math.max(0, elapsed / entry.drawMs);
      } else if (elapsed > entry.shrinkStart) {
        var sp = Math.min(1, (elapsed - entry.shrinkStart) / SPLASH_INK_SHRINK_MS);
        f0 = sp;
        f1 = 1;
      }
      if (f0 < f1) drawTimeRange(entry.geo, f0, f1);
    }

    // 3) 画出线：画完后从头收缩（尾端留在原地）
    for (var e = 0; e < exits.length; e++) {
      var ex = exits[e];
      var lt = (elapsed - ex.start) / ex.dur;
      if (lt <= 0) continue;
      var g0 = 0, g1 = Math.min(1, lt);
      if (lt > 1) {
        var sp2 = Math.min(1, (lt - 1) * ex.dur / SPLASH_INK_SHRINK_MS);
        g0 = sp2;
        g1 = 1;
      }
      if (g0 < g1) drawTimeRange(ex.geo, g0, g1);
    }

    // 4) 正在写的笔画
    for (var j = 0; j < ink.length; j++) {
      var st = ink[j];
      if (st.committed || st.isDroplet) continue;
      var t = (elapsed - st.start) / st.dur;
      if (t <= 0) continue;
      drawTimeRange(st.geo, 0, Math.min(1, t));
    }

    // 5) 水滴点
    drawDroplet(elapsed);
  }

  function tick(now) {
    if (lastFrameAt) {
      var dt = now - lastFrameAt;
      if (dt < 0) dt = 0;
      if (dt > 100) dt = 100;        // 长任务阻塞时钳制，避免整段动画被跳过
      elapsedMs += dt;
    }
    lastFrameAt = now;
    renderFrame(elapsedMs);
    if (elapsedMs >= totalMs) { finish(); return; }
    rafId = requestAnimationFrame(tick);
  }

  function finish() {
    if (finished) return;
    finished = true;
    if (rafId) { cancelAnimationFrame(rafId); rafId = 0; }
    renderFrame(totalMs + 60000);
    canvas.classList.add('done');
  }

  function start() {
    if (started) return;
    started = true;
    finished = false;
    layout();
    if (reduceMotion) { finish(); return; }
    elapsedMs = 0;
    lastFrameAt = 0;
    rafId = requestAnimationFrame(tick);
  }

  var resizeTimer = 0;
  function onResize() {
    if (resizeTimer) return;
    resizeTimer = setTimeout(function () {
      resizeTimer = 0;
      if (!started) return;
      var at = finished ? totalMs + 60000 : elapsedMs;
      layout();
      renderFrame(at);
      if (finished) canvas.classList.add('done');
    }, 120);
  }

  if (window.addEventListener) window.addEventListener('resize', onResize);

  return {
    start: start,
    finish: finish,
    resize: onResize,
    isFinished: function () { return finished; },
    seek: function (ms) {
      started = true;
      if (!ink.length) layout();
      if (rafId) { cancelAnimationFrame(rafId); rafId = 0; }
      reset(true);
      elapsedMs = ms;
      finished = ms >= totalMs;
      renderFrame(ms);
      if (finished) canvas.classList.add('done');
    },
    geometry: function () {
      return {
        entry: !!entry, exits: exits.length, ink: ink.length,
        start: ink.length ? { bodyStart: bodyStart, jumpStart: jumpStart, totalMs: totalMs } : null,
        groups: ink.map(function (o) { return { start: Math.round(o.start), dur: Math.round(o.dur), drop: o.isDroplet }; }),
        css: { w: cssW, h: cssH, dpr: dpr }, elapsed: elapsedMs, finished: finished, reduce: reduceMotion
      };
    }
  };
}

function startSplashInkHandwriting(hwEl) {
  if (splashInkHandle) return true;
  var host = hwEl && hwEl.parentNode;
  if (!host || !document.createElement) return false;
  var canvas = document.createElement('canvas');
  canvas.className = 'splash-ink';
  canvas.setAttribute('aria-hidden', 'true');
  host.appendChild(canvas);
  var reduce = false;
  try {
    reduce = !!reduceSplashMotion ||
      !!(window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches);
  } catch (_) {}
  var renderer = null;
  try {
    renderer = createSplashInkRenderer(canvas, { reduceMotion: reduce, fontEl: hwEl });
  } catch (e) {
    console.warn('[splash] ink renderer init failed:', e);
  }
  if (!renderer) {
    if (canvas.parentNode) canvas.parentNode.removeChild(canvas);
    return false;
  }
  hwEl.classList.add('splash-ink-hidden');
  splashInkHandle = renderer;
  renderer.start();
  return true;
}

function finishSplashInkHandwriting() {
  if (!splashInkHandle) return;
  try { splashInkHandle.finish(); } catch (_) {}
}

// 等 Caveat 字体加载完成后，再触发手写文字动画（兜底路径）
function armSplashHandwrite() {
  var hwEl = document.querySelector('.splash-handwrite');
  if (!hwEl) return;
  // 首选：真笔迹轨迹（不依赖字体，立刻开始）
  try {
    if (startSplashInkHandwriting(hwEl)) return;
  } catch (e) {
    console.warn('[splash] ink handwriting unavailable, fallback to text:', e);
  }
  // 兜底：Caveat 文本 + mask 横向擦除（原逻辑，数据/渲染失败时才走）
  function reveal() { hwEl.classList.add('ready'); }
  if (document.fonts && document.fonts.load) {
    document.fonts.load('600 100px Caveat').then(reveal).catch(function () {
      setTimeout(reveal, 1500);
    });
  } else {
    setTimeout(reveal, 800);
  }
}
armSplashHandwrite();

(function initMineradioSplashCanvas() {
  var canvas = document.getElementById('splash-gl');
  if (!canvas) return;
  var gl = canvas.getContext('webgl', { antialias: true, alpha: false });
  if (!gl) return;

  // ===== 编译 shader =====
  function compile(type, src) {
    var sh = gl.createShader(type);
    gl.shaderSource(sh, src);
    gl.compileShader(sh);
    if (!gl.getShaderParameter(sh, gl.COMPILE_STATUS)) {
      console.error('splash shader compile error:', gl.getShaderInfoLog(sh));
      return null;
    }
    return sh;
  }
  var vsSrc = 'attribute vec2 aPos; void main(){ gl_Position = vec4(aPos, 0.0, 1.0); }';
  var fsSrc = [
    'precision highp float;',
    'uniform vec2 uRes;',
    'uniform float uTime;',
    'uniform vec2 uMouse;',
    'uniform float uMouseForce;',
    'uniform float uIntro;',
    'uniform float uExit;',
    'vec2 hash2(vec2 p){',
    '  p = vec2(dot(p, vec2(127.1, 311.7)), dot(p, vec2(269.5, 183.3)));',
    '  return -1.0 + 2.0 * fract(sin(p) * 43758.5453123);',
    '}',
    'float noise(vec2 p){',
    '  vec2 i = floor(p); vec2 f = fract(p);',
    '  vec2 u = f * f * (3.0 - 2.0 * f);',
    '  return mix(',
    '    mix(dot(hash2(i + vec2(0.0,0.0)), f - vec2(0.0,0.0)),',
    '        dot(hash2(i + vec2(1.0,0.0)), f - vec2(1.0,0.0)), u.x),',
    '    mix(dot(hash2(i + vec2(0.0,1.0)), f - vec2(0.0,1.0)),',
    '        dot(hash2(i + vec2(1.0,1.0)), f - vec2(1.0,1.0)), u.x), u.y);',
    '}',
    'float fbm(vec2 p){',
    '  float v = 0.0; float a = 0.5;',
    '  mat2 rot = mat2(0.8, 0.6, -0.6, 0.8);',
    '  for(int i = 0; i < 6; i++){ v += a * noise(p); p = rot * p * 2.0; a *= 0.5; }',
    '  return v;',
    '}',
    'float field(vec2 uv, vec2 mouse){',
    '  float t = uTime * 0.08;',
    '  vec2 q = vec2(fbm(uv + t), fbm(uv + vec2(5.2, 1.3) - t));',
    '  vec2 r = vec2(',
    '    fbm(uv + 3.0 * q + vec2(1.7, 9.2) + 0.15 * t),',
    '    fbm(uv + 3.0 * q + vec2(8.3, 2.8) + 0.12 * t)',
    '  );',
    '  float pattern = fbm(uv + 3.5 * r);',
    '  float md = length(uv - mouse);',
    '  float ripple = sin(md * 14.0 - uTime * 2.0) * exp(-md * 3.0);',
    '  float attract = exp(-md * 2.2) * (0.6 + 0.4 * uMouseForce);',
    '  float introScale = mix(0.15, 1.0, smoothstep(0.0, 1.0, uIntro));',
    '  float d = length(uv) / introScale;',
    '  float breathe = 0.9 + 0.1 * sin(uTime * 0.5);',
    '  float coreGlow = exp(-d * 2.3) * 1.4 * breathe;',
    '  float haloGlow = exp(-d * 0.9) * 0.6;',
    '  float intensity = pattern * 0.55 + coreGlow + haloGlow + attract * 0.6 + ripple * 0.18 * uMouseForce;',
    '  return intensity * mix(0.2, 1.0, uIntro);',
    '}',
    'void main(){',
    '  vec2 uv = (gl_FragCoord.xy - 0.5 * uRes.xy) / uRes.y;',
    '  vec2 mouse = (uMouse - 0.5) * vec2(uRes.x / uRes.y, 1.0);',
    '  float rd = length(uv);',
    '  vec2 dir = uv * rd * 0.012;',
    '  float iR = field(uv + dir, mouse);',
    '  float iG = field(uv, mouse);',
    '  float iB = field(uv - dir, mouse);',
    '  vec3 paper = vec3(0.93, 0.95, 0.99);',
    '  vec3 soft  = vec3(0.62, 0.79, 0.98);',
    '  vec3 blue  = vec3(0.24, 0.54, 0.94);',
    '  vec3 core  = vec3(0.98, 0.99, 1.00);',
    '  vec3 col;',
    '  col.r = mix(paper.r, mix(soft.r, mix(blue.r, core.r, smoothstep(0.9, 1.35, iR)), smoothstep(0.4, 0.95, iR)), smoothstep(0.05, 0.5, iR));',
    '  col.g = mix(paper.g, mix(soft.g, mix(blue.g, core.g, smoothstep(0.9, 1.35, iG)), smoothstep(0.4, 0.95, iG)), smoothstep(0.05, 0.5, iG));',
    '  col.b = mix(paper.b, mix(soft.b, mix(blue.b, core.b, smoothstep(0.9, 1.35, iB)), smoothstep(0.4, 0.95, iB)), smoothstep(0.05, 0.5, iB));',
    '  float md = length(uv - mouse);',
    '  float attract = exp(-md * 2.4);',
    '  col = mix(col, blue, attract * 0.25 * uMouseForce);',
    '  float sparkle = 0.0;',
    '  for(int i = 0; i < 5; i++){',
    '    float fi = float(i);',
    '    vec2 sp = hash2(vec2(fi * 12.3, fi * 7.1));',
    '    sp.x += sin(uTime * (0.1 + fi * 0.03) + fi) * 0.35;',
    '    sp.y += cos(uTime * (0.08 + fi * 0.04) + fi * 2.0) * 0.35;',
    '    float sd = length(uv - sp * vec2(uRes.x / uRes.y, 1.0) * 0.5);',
    '    sparkle += 0.005 / (sd + 0.004);',
    '  }',
    '  col = mix(col, blue, clamp(sparkle * 0.15 * uIntro, 0.0, 0.5));',
    '  float grain = hash2(gl_FragCoord.xy + uTime).x;',
    '  col += (grain - 0.5) * 0.018;',
    '  float vign = 1.0 - 0.12 * dot(uv, uv);',
    '  col *= vign;',
    '  if (uExit > 0.0) {',
    '    float e = uExit;',
    '    float d = length(uv);',
    '    float burst = exp(-d * mix(2.3, 0.2, e)) * (1.0 + e * 4.0);',
    '    col = mix(col, vec3(1.0), smoothstep(0.0, 1.0, burst * e));',
    '    col = mix(col, vec3(1.0), smoothstep(0.6, 1.0, e));',
    '  }',
    '  gl_FragColor = vec4(col, 1.0);',
    '}'
  ].join('\n');

  var vs = compile(gl.VERTEX_SHADER, vsSrc);
  var fs = compile(gl.FRAGMENT_SHADER, fsSrc);
  if (!vs || !fs) return;
  var prog = gl.createProgram();
  gl.attachShader(prog, vs);
  gl.attachShader(prog, fs);
  gl.linkProgram(prog);
  if (!gl.getProgramParameter(prog, gl.LINK_STATUS)) {
    console.error('splash program link error:', gl.getProgramInfoLog(prog));
    return;
  }
  gl.useProgram(prog);

  // 确保首帧有颜色，避免 WebGL 失败时 canvas 显示为黑/透明
  gl.clearColor(0.93, 0.95, 0.99, 1.0);
  gl.clear(gl.COLOR_BUFFER_BIT);

  var buf = gl.createBuffer();
  gl.bindBuffer(gl.ARRAY_BUFFER, buf);
  gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 3, -1, -1, 3]), gl.STATIC_DRAW);
  var aPos = gl.getAttribLocation(prog, 'aPos');
  gl.enableVertexAttribArray(aPos);
  gl.vertexAttribPointer(aPos, 2, gl.FLOAT, false, 0, 0);

  var uRes = gl.getUniformLocation(prog, 'uRes');
  var uTime = gl.getUniformLocation(prog, 'uTime');
  var uMouse = gl.getUniformLocation(prog, 'uMouse');
  var uMouseForce = gl.getUniformLocation(prog, 'uMouseForce');
  var uIntro = gl.getUniformLocation(prog, 'uIntro');
  var uExit = gl.getUniformLocation(prog, 'uExit');

  // 性能检测
  var quality = 1.0;
  (function detectPerf() {
    var isMobile = /Android|iPhone|iPad|iPod/i.test(navigator.userAgent);
    var cores = navigator.hardwareConcurrency || 4;
    if (isMobile || cores <= 4) quality = 0.65;
  })();

  var dpr = 1;
  function resize() {
    dpr = Math.min(window.devicePixelRatio || 1, 2) * quality;
    canvas.width = Math.floor(window.innerWidth * dpr);
    canvas.height = Math.floor(window.innerHeight * dpr);
    gl.viewport(0, 0, canvas.width, canvas.height);
  }
  window.addEventListener('resize', resize);
  resize();

  // 鼠标交互
  var mx = 0.5, my = 0.5, cmx = 0.5, cmy = 0.5, force = 0;
  function setPointer(x, y) {
    mx = x / window.innerWidth;
    my = 1.0 - y / window.innerHeight;
    force = 1.0;
  }
  window.addEventListener('mousemove', function(e) { setPointer(e.clientX, e.clientY); });
  window.addEventListener('touchmove', function(e) {
    if (e.touches[0]) setPointer(e.touches[0].clientX, e.touches[0].clientY);
  }, { passive: true });

  // 渲染循环
  var start = performance.now();
  var frameCount = 0, lastCheck = performance.now(), degraded = false;

  // 暴露退出接口给 dismissSplash
  window.splashGlExit = { started: false, startAt: 0 };

  function frame(now) {
    if (!splashAnimating) return;
    var t = (now - start) / 1000;

    cmx += (mx - cmx) * 0.06;
    cmy += (my - cmy) * 0.06;
    force *= 0.96;

    var intro = Math.min(t / 2.5, 1.0);
    var introEased = intro * intro * (3.0 - 2.0 * intro);

    var exit = 0;
    if (window.splashGlExit && window.splashGlExit.started) {
      exit = Math.min((now - window.splashGlExit.startAt) / 1400, 1.0);
    }

    gl.uniform2f(uRes, canvas.width, canvas.height);
    gl.uniform1f(uTime, t);
    gl.uniform2f(uMouse, cmx, cmy);
    gl.uniform1f(uMouseForce, force);
    gl.uniform1f(uIntro, introEased);
    gl.uniform1f(uExit, exit);

    gl.drawArrays(gl.TRIANGLES, 0, 3);

    frameCount++;
    if (now - lastCheck >= 1000) {
      var fps = frameCount * 1000 / (now - lastCheck);
      frameCount = 0; lastCheck = now;
      if (fps < 40 && !degraded) {
        degraded = true;
        quality = Math.max(0.5, quality * 0.7);
        resize();
      }
    }
    requestAnimationFrame(frame);
  }
  requestAnimationFrame(frame);
})();

function playMineradioIntroSound() {
  if (splashSoundPlayed) return;
  try {
    var AudioContextCtor = window.AudioContext || window.webkitAudioContext;
    if (!AudioContextCtor) return;
    var ctx = splashAudioCtx || new AudioContextCtor();
    splashAudioCtx = ctx;
    if (ctx.state === 'suspended' && ctx.resume) {
      ctx.resume().then(function(){
        if (!splashSoundPlayed) playMineradioIntroSound();
      }).catch(function(){});
      if (ctx.state === 'suspended') return;
    }
    splashSoundPlayed = true;

    var now = ctx.currentTime + 0.02;
    var master = ctx.createGain();
    master.gain.setValueAtTime(0.0001, now);
    master.gain.exponentialRampToValueAtTime(0.062, now + 0.16);
    master.gain.exponentialRampToValueAtTime(0.040, now + 3.35);
    master.gain.exponentialRampToValueAtTime(0.0001, now + 5.28);
    master.connect(ctx.destination);

    var noiseBuffer = ctx.createBuffer(1, Math.floor(ctx.sampleRate * 2.45), ctx.sampleRate);
    var data = noiseBuffer.getChannelData(0);
    for (var i = 0; i < data.length; i++) {
      var tail = 1 - i / data.length;
      data[i] = (Math.random() * 2 - 1) * Math.pow(tail, 1.35);
    }
    var noise = ctx.createBufferSource();
    var noiseGain = ctx.createGain();
    var noiseFilter = ctx.createBiquadFilter();
    noise.buffer = noiseBuffer;
    noiseFilter.type = 'bandpass';
    noiseFilter.frequency.setValueAtTime(720, now);
    noiseFilter.frequency.exponentialRampToValueAtTime(2400, now + 2.2);
    noiseFilter.Q.setValueAtTime(0.72, now);
    noiseGain.gain.setValueAtTime(0.0001, now);
    noiseGain.gain.exponentialRampToValueAtTime(0.020, now + 0.12);
    noiseGain.gain.exponentialRampToValueAtTime(0.010, now + 1.60);
    noiseGain.gain.exponentialRampToValueAtTime(0.0001, now + 2.42);
    noise.connect(noiseFilter); noiseFilter.connect(noiseGain); noiseGain.connect(master);
    noise.start(now); noise.stop(now + 2.46);

    var low = ctx.createOscillator();
    var lowGain = ctx.createGain();
    low.type = 'sine';
    low.frequency.setValueAtTime(86, now + 0.18);
    low.frequency.exponentialRampToValueAtTime(43, now + 1.18);
    lowGain.gain.setValueAtTime(0.0001, now + 0.12);
    lowGain.gain.exponentialRampToValueAtTime(0.032, now + 0.30);
    lowGain.gain.exponentialRampToValueAtTime(0.0001, now + 1.34);
    low.connect(lowGain); lowGain.connect(master);
    low.start(now + 0.12); low.stop(now + 1.40);

    function softTone(type, f0, f1, startAt, dur, peak) {
      var osc = ctx.createOscillator();
      var gain = ctx.createGain();
      var filter = ctx.createBiquadFilter();
      osc.type = type;
      osc.frequency.setValueAtTime(f0, now + startAt);
      osc.frequency.exponentialRampToValueAtTime(f1, now + startAt + dur * 0.72);
      filter.type = 'lowpass';
      filter.frequency.setValueAtTime(3400, now + startAt);
      gain.gain.setValueAtTime(0.0001, now + startAt);
      gain.gain.exponentialRampToValueAtTime(peak, now + startAt + 0.08);
      gain.gain.exponentialRampToValueAtTime(0.0001, now + startAt + dur);
      osc.connect(filter); filter.connect(gain); gain.connect(master);
      osc.start(now + startAt);
      osc.stop(now + startAt + dur + 0.04);
    }
    softTone('triangle', 440, 660, 1.05, 0.72, 0.018);
    softTone('sine', 880, 1320, 2.10, 0.86, 0.013);
    softTone('triangle', 1180, 1760, 2.72, 0.52, 0.010);
    softTone('triangle', 660, 1180, 3.32, 0.82, 0.014);
    softTone('sine', 1760, 1040, 3.64, 0.46, 0.010);
  } catch (e) {}
}
function armSplashSoundFallback() {
  if (splashSoundFallbackArmed) return;
  splashSoundFallbackArmed = true;
  function unlock() {
    if (!splashSoundPlayed) playMineradioIntroSound();
    document.removeEventListener('pointerdown', unlock, true);
    document.removeEventListener('keydown', unlock, true);
  }
  document.addEventListener('pointerdown', unlock, true);
  document.addEventListener('keydown', unlock, true);
}

function dismissSplash() {
  var s = document.getElementById('splash');
  if (!s || s.classList.contains('hide') || s.classList.contains('exiting')) return;
  markAppPerf('splash-dismiss');
  finishSplashInkHandwriting();
  if (splashTimer) { clearTimeout(splashTimer); splashTimer = null; }
  splashReadyToEnter = false;
  s.classList.remove('ready');
  if (typeof shouldUseIdleWallpaperPreview === 'function'
    ? shouldUseIdleWallpaperPreview(true)
    : (typeof shouldShowEmptyHomeAfterSplash === 'function' && shouldShowEmptyHomeAfterSplash())) {
    activateHomeWallpaperPreview();
  }
  revealIdleParticles(0, reduceSplashMotion ? 700 : 2400);
  document.body.classList.add('splash-revealing');
  s.classList.add('exiting');
  // 触发 Aurora shader 的退出动画（向中心汇聚过曝到白）
  if (window.splashGlExit) {
    window.splashGlExit.started = true;
    window.splashGlExit.startAt = performance.now();
  }

  var content = s.querySelector('.splash-content');
  if (content) {
    content.style.transition = 'opacity 680ms cubic-bezier(.22,1,.36,1), transform 980ms cubic-bezier(.22,1,.36,1)';
    content.style.opacity = '0';
    content.style.transform = 'translateY(-14px) scale(.986)';
  }

  setTimeout(function() {
    s.classList.add('hide');
    splashAnimating = false;
    document.body.classList.remove('splash-active');
    document.body.classList.remove('splash-revealing');
    markAppPerf('home-revealed');
    if (s && s.parentNode) s.style.display = 'none';
    requestAnimationFrame(function(){
      var homeShown = updateEmptyHomeVisibility({ forceLoad: true });
      if (!homeShown && shouldForceEmptyHomeAfterSplash()) {
        homeSuppressed = false;
        homeForcedOpen = true;
        homeShown = updateEmptyHomeVisibility({ forceLoad: true });
      }
      requestAnimationFrame(function(){
        updateVisualGuideButtonVisibility();
        var guideStarted = maybeRunStartupVisualGuide('splash');
        scheduleStartupLoginGuide('splash', guideStarted);
        setTimeout(maybeShowUploadTipOnce, 5200);
      });
    });
  }, 1180);
}

function markSplashReadyToEnter() {
  var s = document.getElementById('splash');
  if (!s || s.classList.contains('hide') || s.classList.contains('exiting')) return;
  markAppPerf('splash-ready');
  splashReadyToEnter = true;
  splashTimer = null;
  s.classList.add('ready');
  s.setAttribute('role', 'button');
  s.setAttribute('tabindex', '0');
  s.setAttribute('aria-label', '点击进入 Mineradio');
  // 用户在 ready 前已点过：立刻进入
  if (splashPendingEnter) {
    splashPendingEnter = false;
    requestSplashEnterNow();
  }
}

function requestSplashEnterNow() {
  // 模块未就绪时只记录意图，不提前进入
  if (!window.__mineradioCoreModulesReady && !splashReadyToEnter) {
    splashPendingEnter = true;
    return;
  }
  try { playMineradioIntroSound(); } catch (_) {}
  if (splashReadyToEnter) dismissSplash();
  else splashPendingEnter = true;
}

function tryMarkSplashReadyFromBoot() {
  if (splashReadyToEnter) return;
  // 必须等 index-loader 注入完主波（__mineradioCoreModulesReady）才能给「点击进入」
  if (!window.__mineradioCoreModulesReady) {
    if (splashTimer) clearTimeout(splashTimer);
    splashTimer = setTimeout(tryMarkSplashReadyFromBoot, 80);
    return;
  }
  var minMs = reduceSplashMotion ? 900 : 1500;
  var elapsed = splashShownAt ? (performance.now() - splashShownAt) : 0;
  if (elapsed < minMs) {
    if (splashTimer) clearTimeout(splashTimer);
    splashTimer = setTimeout(tryMarkSplashReadyFromBoot, Math.max(50, minMs - elapsed));
    return;
  }
  markSplashReadyToEnter();
}

function initSplashDomBindings() {
  updateVisualGuideButtonVisibility();
  paintHomeLocalSnapshot();
  var s = document.getElementById('splash');
  if (!s) return;
  markAppPerf('dom-content-loaded');
  splashShownAt = performance.now();
  armSplashSoundFallback();
  prewarmHomeWallpaperPreview();
  function requestSplashEnter() {
    requestSplashEnterNow();
  }
  s.addEventListener('click', requestSplashEnter);
  document.addEventListener('keydown', function(e){
    if (!document.body.classList.contains('splash-active')) return;
    if (e.key === 'Enter' || e.code === 'Space') {
      e.preventDefault();
      requestSplashEnter();
    }
  });
  // 最短展示：与进度条 minFillMs 对齐，保证能看见爬升
  var minMs = reduceSplashMotion ? 900 : 1500;
  if (reduceSplashMotion) s.classList.add('reduce-motion');
  playMineradioIntroSound();
  if (splashTimer) clearTimeout(splashTimer);
  splashTimer = setTimeout(tryMarkSplashReadyFromBoot, minMs);
}
if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', initSplashDomBindings);
} else {
  initSplashDomBindings();
}

// ============================================================
//  启动（单条语句失败不得阻断后续模块，尤其是 11-main-loop）
// ============================================================
try {
applyDiyMode(diyPlayerMode, { save: false });
// 只绑全局交互（快捷键/toggle）；面板 DOM 绑定延后到 idle/首次打开，视觉由 setPreset 独立生效
bindFxGlobalInteractions();
if (typeof scheduleFxPanelDomBind === 'function') scheduleFxPanelDomBind();
if (typeof migratePerformanceQualityTowardAutoOnce === 'function') migratePerformanceQualityTowardAutoOnce();
// 低配 auto→eco 时把封面粒子网格压下来（默认 1.55≈183² 是播放 CPU 大头）
if (typeof applyCoverParticleResolution === 'function' && fx) {
  try { applyCoverParticleResolution(fx.coverResolution, { reload: false }); } catch (_) {}
}
applySavedLyricPaletteState();
// 加载已保存的淡入淡出偏好
(function(){
  try {
    var saved = JSON.parse(localStorage.getItem('mineradio-audio-fade-v1'));
    if (saved && saved.in) AUDIO_FADE_IN_MS = normalizeAudioFadeMs(saved.in, 460);
    if (saved && saved.out) AUDIO_FADE_OUT_MS = normalizeAudioFadeMs(saved.out, 420);
  } catch (_) {}
})();
bindQualityControl();
bindMoodAudioControl();
bindSleepTimerControl();
bindVolumeControls();
initControlGlassSurface();
bindPlayerControlAnimations();
scheduleUiWarmTask(function(){
  updateControlGlassDisplacementMap();
  updateSearchBoxGlassDisplacementMap();
  updateSearchPillGlassDisplacementMap();
  try {
    if (renderer && renderer.compile && scene && camera) renderer.compile(scene, camera);
  } catch (e) {}
}, 900);
applyUserCapsuleAutoHideState();
applyFxFabAutoHideState();
applyControlsAutoHidePreference();
applyDesktopLyricsState(false);
applyWallpaperModeState(false);
setShelfMode(fx.shelf);
applyStartupStarfieldPreset();
applyPlaylistPanelPinState(false);
// 重资产初始化挪到首帧后，缩短 splash 内同步阻塞
scheduleUiWarmTask(function(){
  if (fx.floatLayer) {
    try { createFloatLayer(); } catch (err) { console.warn('[boot] createFloatLayer failed:', err); }
  }
  if (fx.particleLyrics && !isClassicPresetActive()) {
    try { createLyricsParticles(); } catch (err) { console.warn('[boot] createLyricsParticles failed:', err); }
  }
  if (fx.backCover) {
    try { createBackCoverLayer(); } catch (err) { console.warn('[boot] createBackCoverLayer failed:', err); }
  }
}, 0);
initIdleGuideCanvas();
} catch (bootErr) {
  console.error('[boot] startup block failed (continuing to main-loop):', bootErr);
}
// 主波 boot 主路径跑完：若已过最短 splash 时长则立刻可点进（不再干等 4s）
try { tryMarkSplashReadyFromBoot(); } catch (_) {}
function bootstrapStartupLoginStatus() {
  startupLoginStatusPromise = Promise.all([
    typeof refreshLoginStatus === 'function' ? refreshLoginStatus() : Promise.resolve(null),
    typeof refreshQQLoginStatus === 'function' ? refreshQQLoginStatus({ forceVip: true, reason: 'startup' }) : Promise.resolve(null),
    typeof refreshKugouLoginStatus === 'function' ? refreshKugouLoginStatus() : Promise.resolve(null),
    typeof refreshQishuiLoginStatus === 'function' ? refreshQishuiLoginStatus() : Promise.resolve(null),
    typeof refreshSpotifyLoginStatus === 'function' ? refreshSpotifyLoginStatus() : Promise.resolve(null)
  ]);
  // Keep a named hook for 05-startup-bindings.js / guards.
  if (typeof ensureStartupQQVipRecheck === 'function') { /* already included above */ }
  return startupLoginStatusPromise;
}
function paintHomeLocalSnapshot() {
  if (!homeDiscoverState.loaded && Mineradio.home && typeof Mineradio.home.readCache === 'function') {
    hydrateHomeDiscoverFromCache();
  }
  if (!homeWeatherRadioState.loaded) hydrateHomeWeatherFromCache();
  syncContinueCard();
  renderHomeDiscover();
  refreshContinueCardLive();
  bootstrapScenePresets(false);
}
function handleStartupLoginReady() {
  if (hasAnyPlatformLogin()) {
    homeDiscoverState.loggedIn = true;
    refreshUserPlaylists(true);
    if (!homeDiscoverState.loaded) {
      if (hydrateHomeDiscoverFromCache()) { /* cached */ }
    }
    if (!homeDiscoverState.loading) loadHomeDiscover(true);
  }
  maybeRestorePlaybackSessionOnStartup();
  initHomeSceneRow();
  bootstrapScenePresets(false);
  paintHomeLocalSnapshot();
  if (document.body.classList.contains('splash-active')) return;
  var homeShown = updateEmptyHomeVisibility({ forceLoad: hasAnyPlatformLogin() });
  if (!hasAnyPlatformLogin()) scheduleStartupLoginGuide('status', false);
  else if (homeShown) renderHomeDiscover();
}
bootstrapStartupLoginStatus();
startQQLoginStatusAutoRefresh();
if (typeof startKugouLoginStatusAutoRefresh === 'function') startKugouLoginStatusAutoRefresh();
if (typeof startQishuiLoginStatusAutoRefresh === 'function') startQishuiLoginStatusAutoRefresh();
if (typeof startSpotifyLoginStatusAutoRefresh === 'function') startSpotifyLoginStatusAutoRefresh();
if (startupLoginStatusPromise && startupLoginStatusPromise.then) {
  startupLoginStatusPromise.then(handleStartupLoginReady).catch(function(e){
    console.warn('[StartupLogin]', e);
    handleStartupLoginReady();
  });
}
var collectNameInput = document.getElementById('collect-new-name');
if (collectNameInput) {
  collectNameInput.addEventListener('keydown', function(e){
    if (e.key === 'Enter') {
      e.preventDefault();
      createPlaylistFromCollect();
    }
  });
}
var customLyricInput = document.getElementById('custom-lyric-input');
if (customLyricInput) {
  customLyricInput.addEventListener('keydown', function(e){
    if ((e.ctrlKey || e.metaKey) && e.key === 'Enter') {
      e.preventDefault();
      saveCustomLyricForCurrent();
    }
  });
}
safeRenderQueuePanel('startup');
updateCustomCoverButton();
updateCustomLyricControls();
updateLikeButtons();
setTimeout(function () {
  if (typeof initUpdatePreview === 'function') initUpdatePreview();
}, 9000);

